description:
An `HRESULT` is a 32-bit value: the top bit is set for failure, bits 16-26 are the **facility** (7 means "a Win32 error code"), and the low 16 bits are the **code**. Write the helpers:

```cpp
using DWORD = std::uint32_t;
using HRESULT = std::int32_t;

bool failed(HRESULT hr);
HRESULT hresultFromWin32(DWORD error);
int facility(HRESULT hr);              // (hr >> 16) & 0x7FF
int code(HRESULT hr);                  // hr & 0xFFFF
std::string describe(HRESULT hr);
std::string trimLineBreaks(std::string text);
```

- `hresultFromWin32` works like the Windows macro: 0 stays 0 (success); any other code becomes `0x80000000 | (7 << 16) | (error & 0xFFFF)`.
- `describe` gives `"S_OK"` for 0, `"0x80070005 (Win32 error 5)"` for a failure with facility 7, `"0x80004005"` for other failures, and `"success 0x00000001"` for other successes (hex with 8 lower-case digits).
- `trimLineBreaks` removes every `\r` and `\n` from the **end** of a message, as `FormatMessageW` leaves them there.

starter.solution.cpp:
#include <cstdint>
#include <string>

using DWORD = std::uint32_t;
using HRESULT = std::int32_t;

bool failed(HRESULT hr) { return false; }
HRESULT hresultFromWin32(DWORD error) { return 0; }
int facility(HRESULT hr) { return 0; }
int code(HRESULT hr) { return 0; }
std::string describe(HRESULT hr) { return ""; }
std::string trimLineBreaks(std::string text) { return text; }

solution.solution.cpp:
#include <cstdint>
#include <cstdio>
#include <string>

using DWORD = std::uint32_t;
using HRESULT = std::int32_t;

bool failed(HRESULT hr) { return hr < 0; }

HRESULT hresultFromWin32(DWORD error)
{
    if (error == 0) return 0;
    return static_cast<HRESULT>(0x80000000u | (7u << 16) | (error & 0xFFFFu));
}

int facility(HRESULT hr) { return static_cast<int>((static_cast<std::uint32_t>(hr) >> 16) & 0x7FFu); }
int code(HRESULT hr) { return static_cast<int>(static_cast<std::uint32_t>(hr) & 0xFFFFu); }

std::string describe(HRESULT hr)
{
    if (hr == 0) return "S_OK";
    char hex[16];
    std::snprintf(hex, sizeof(hex), "0x%08x", static_cast<unsigned>(static_cast<std::uint32_t>(hr)));
    if (!failed(hr)) return std::string("success ") + hex;
    if (facility(hr) == 7) return std::string(hex) + " (Win32 error " + std::to_string(code(hr)) + ")";
    return hex;
}

std::string trimLineBreaks(std::string text)
{
    while (!text.empty() && (text.back() == '\r' || text.back() == '\n')) text.pop_back();
    return text;
}

unitTests:
TEST("failure bit") { CHECK(failed(static_cast<HRESULT>(0x80004005u))); CHECK(!failed(0)); CHECK(!failed(1)); }
TEST("from Win32") { CHECK_EQ(static_cast<std::uint32_t>(hresultFromWin32(5)), 0x80070005u); CHECK_EQ(hresultFromWin32(0), 0); CHECK_EQ(static_cast<std::uint32_t>(hresultFromWin32(1223)), 0x800704C7u); }
TEST("fields") { const HRESULT hr = hresultFromWin32(32); CHECK_EQ(facility(hr), 7); CHECK_EQ(code(hr), 32); CHECK_EQ(facility(static_cast<HRESULT>(0x80004005u)), 0); }
TEST("descriptions") {
    CHECK_EQ(describe(0), std::string("S_OK")); CHECK_EQ(describe(hresultFromWin32(5)), std::string("0x80070005 (Win32 error 5)"));
    CHECK_EQ(describe(static_cast<HRESULT>(0x80004005u)), std::string("0x80004005")); CHECK_EQ(describe(1), std::string("success 0x00000001"));
}
TEST("trimming") { CHECK_EQ(trimLineBreaks("Access is denied.\r\n"), std::string("Access is denied.")); CHECK_EQ(trimLineBreaks("a\r\nb\n\n"), std::string("a\r\nb")); CHECK_EQ(trimLineBreaks(""), std::string("")); }

